import { MediaItem } from 'flow-sdk';

export interface SceneState {
  userX: number; // 0-100 (percentage of stage width)
  userY: number; // 0-100 (percentage of stage height)
  userScale: number; // Multiplier
  userBrightness: number;
  userContrast: number;
  maskThreshold: number;
  maskBlur: number; // Legacy
  maskChoke: number; // -50 to 50
  maskFeather: number; // 0 to 20
  maskSmoothing: number; // 0 to 0.95
  showOverlay: boolean;
  backgroundMedia: MediaItem | null;
  isBackgroundAudioEnabled: boolean;
  isFlipped: boolean;
}

export interface TransformState {
  isDragging: boolean;
  isResizing: boolean;
  startX: number;
  startY: number;
  startUserX: number; startUserY: number;
  startUserScale: number;
  resizeHandle: string | null;
}

import { FilesetResolver, ImageSegmenter } from '@mediapipe/tasks-vision';

export class SegmentationService {
  private segmenter: ImageSegmenter | null = null;
  private isInitializing: boolean = false;

  async init() {
    if (this.segmenter || this.isInitializing) return;
    this.isInitializing = true;

    try {
      const vision = await FilesetResolver.forVisionTasks(
        "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
      );

      this.segmenter = await ImageSegmenter.createFromOptions(vision, {
        baseOptions: {
          modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter_landscape/float16/latest/selfie_segmenter_landscape.tflite",
          delegate: "GPU"
        },
        runningMode: "VIDEO",
        outputCategoryMask: false,
        outputConfidenceMasks: true
      });
    } catch (err) {
      console.error('Failed to initialize MediaPipe ImageSegmenter:', err);
    } finally {
      this.isInitializing = false;
    }
  }

  getSegmenter() {
    return this.segmenter;
  }

  close() {
    if (this.segmenter) {
      this.segmenter.close();
      this.segmenter = null;
    }
  }
}

export const segmentationService = new SegmentationService();

import { useEffect, useRef, useState, useCallback } from 'react';
import { Flow } from 'flow-sdk';

export function useWebcam() {
  const streamRef = useRef<any>(null);
  const [isStreaming, setIsStreaming] = useState(false);
  const [resolution, setResolution] = useState({ width: 0, height: 0 });
  const latestFrame = useRef<ImageBitmap | null>(null);

  const stop = useCallback(async () => {
    if (streamRef.current) {
      try {
        // Try to call stop on the stream handle
        await streamRef.current.stop();
      } catch (err) {
        // Handle cases where the stream might already be closed/invalidated by the host
        console.warn('Gracefully handled stream stop error:', err);
      } finally {
        // Always reset internal state
        streamRef.current = null;
        setIsStreaming(false);
      }
    }

    if (latestFrame.current) {
      latestFrame.current.close();
      latestFrame.current = null;
    }
  }, []);

  const start = useCallback(async () => {
    // If already streaming, stop first to clear state
    if (isStreaming) {
      await stop();
    }

    try {
      const stream = await Flow.camera.stream({
        facingMode: 'user',
        frameRate: 30,
        resolution: 'high'
      });

      streamRef.current = stream;
      setResolution({ width: stream.width, height: stream.height });
      setIsStreaming(true);

      stream.onFrame(({ bitmap }: { bitmap: ImageBitmap }) => {
        // Guard against frames with 0 dimensions or null
        if (!bitmap || bitmap.width === 0 || bitmap.height === 0) {
          bitmap?.close();
          return;
        }

        // If the hook state changed while we were waiting for a frame, stop
        if (!streamRef.current) {
          bitmap.close();
          return;
        }

        if (latestFrame.current) {
          latestFrame.current.close();
        }
        latestFrame.current = bitmap;
      });
    } catch (err) {
      console.error('Failed to start webcam:', err);
      setIsStreaming(false);
      streamRef.current = null;
    }
  }, [isStreaming, stop]);

  // Handle tab visibility and page unmount
  useEffect(() => {
    const handleVisibilityChange = () => {
      // If the tab is hidden (e.g. user changed tabs), the host will likely
      // invalidate the stream ID. We stop proactively to keep state in sync.
      if (document.visibilityState === 'hidden' && streamRef.current) {
        stop();
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      stop();
    };
  }, [stop]);

  return { 
    start, 
    stop, 
    isStreaming, 
    resolution, 
    latestFrame 
  };
}

import React, { useState, useEffect, useRef } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
  className?: string;
}> = ({ icon, children, variant = 'filled', onClick, disabled, className = '' }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]} ${className}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const RangeSlider: React.FC<{
  label: string; 
  value: number; 
  min: number; 
  max: number;
  step?: number; 
  formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input 
        type="range" 
        min={min} 
        max={max} 
        step={step} 
        value={value}
        onChange={(e) => onChange(Number(e.target.value))} 
        className="w-full"
      />
    </div>
  </div>
);

export const DragNumberField: React.FC<{
  label: string; 
  value: number; 
  min?: number; 
  max?: number;
  step?: number; 
  suffix?: string; 
  onChange: (val: number) => void; 
  className?: string;
}> = ({ label, value, min = 0, max = 999, step = 1, suffix = '', onChange, className = '' }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };
    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = Math.round((dragRef.current.startVal + delta * step) / step) * step;
        onChange(Math.min(max, Math.max(min, newVal)));
        document.body.style.cursor = 'ns-resize';
      }
    };
    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      if (!wasDrag) {
        setEditValue(String(value));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div className={`border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none transition-colors ${isEditing ? '' : 'cursor-ns-resize'} ${className}`}
      onMouseDown={handleMouseDown}>
      <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input ref={inputRef} type="text" value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') commitEdit(editValue); if (e.key === 'Escape') setIsEditing(false); }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0" autoFocus />
        ) : (
          <>
            <span className="text-[11px] font-medium text-white tracking-[0.1px] cursor-text">{value}{suffix}</span>
            <div className="flex flex-col items-center mr-1.5 -gap-px text-white/40">
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 0L9 5H1L5 0Z" fill="currentColor"/></svg>
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 6L1 1H9L5 6Z" fill="currentColor"/></svg>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useImperativeHandle, forwardRef } from 'react';
import { SceneState } from '../types';
import { segmentationService } from '../services/segmentationService';

interface CanvasStageProps {
  scene: SceneState;
  onSceneChange: (updates: Partial<SceneState>) => void;
  latestFrame: React.RefObject<ImageBitmap | null>;
  isStreaming: boolean;
  forceMute?: boolean;
}

export interface CanvasStageHandle {
  capture: () => Promise<string>;
  startRecording: () => void;
  stopRecording: () => Promise<string>;
}

const HANDLE_SIZE = 12;
const HIT_PADDING = 10;

const CanvasStage = forwardRef<CanvasStageHandle, CanvasStageProps>(({ 
  scene, 
  onSceneChange, 
  latestFrame, 
  isStreaming,
  forceMute = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const bgVideoRef = useRef<HTMLVideoElement>(null);
  const bgImageRef = useRef<HTMLImageElement>(null);

  const sceneRef = useRef(scene);
  useEffect(() => { sceneRef.current = scene; }, [scene]);

  // Intermediate canvases for mask processing
  const grabCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const maskCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const tempMaskCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const userCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));

  // Ref to track last segmentation data for temporal smoothing
  const previousMaskDataRef = useRef<Float32Array | null>(null);
  const userGeometryRef = useRef({ x: 0, y: 0, w: 0, h: 0 });

  const interactionRef = useRef({
    type: 'none' as 'none' | 'drag' | 'resize',
    startX: 0, startY: 0,
    startUserX: 0, startUserY: 0,
    startUserScale: 0,
    resizeHandle: '' as 'tl' | 'tr' | 'bl' | 'br' | '',
    fixedX: 0, fixedY: 0, // Pinned corner in canvas pixels
    startDist: 0         // Distance from fixed point to initial pointer
  });

  const isRecordingRef = useRef(false);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  useEffect(() => {
    segmentationService.init();
    return () => segmentationService.close();
  }, []);

  useEffect(() => {
    let currentBlobUrl: string | null = null;

    if (scene.backgroundMedia?.type === 'video') {
      if (bgVideoRef.current) {
        const bytes = Uint8Array.from(atob(scene.backgroundMedia.base64), c => c.charCodeAt(0));
        const blob = new Blob([bytes], { type: scene.backgroundMedia.mimeType });
        currentBlobUrl = URL.createObjectURL(blob);

        bgVideoRef.current.src = currentBlobUrl;
        bgVideoRef.current.crossOrigin = 'anonymous';
        bgVideoRef.current.load();
        // Explicitly play to ensure it doesn't get stuck on the first frame
        bgVideoRef.current.play().catch(err => {
          console.warn('Background video play failed:', err);
        });
      }
    } else if (scene.backgroundMedia?.type === 'image' && bgImageRef.current) {
      bgImageRef.current.src = `data:${scene.backgroundMedia.mimeType};base64,${scene.backgroundMedia.base64}`;
    }

    return () => {
      if (currentBlobUrl) {
        URL.revokeObjectURL(currentBlobUrl);
      }
    };
  }, [scene.backgroundMedia]);

  useEffect(() => {
    if (bgVideoRef.current) {
      bgVideoRef.current.muted = !scene.isBackgroundAudioEnabled || forceMute;
    }
  }, [scene.isBackgroundAudioEnabled, forceMute]);

  useImperativeHandle(ref, () => ({
    capture: async () => {
      const canvas = canvasRef.current;
      if (!canvas) return '';
      await renderLoop(true);
      return canvas.toDataURL('image/png').split(',')[1];
    },
    startRecording: () => {
      const canvas = canvasRef.current;
      if (!canvas || isRecordingRef.current) return;
      const stream = canvas.captureStream(30);
      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
      chunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      isRecordingRef.current = true;
      recorderRef.current = recorder;
      recorder.start();
    },
    stopRecording: () => {
      return new Promise((resolve, reject) => {
        const recorder = recorderRef.current;
        if (!recorder) return reject('Not recording');
        recorder.onstop = async () => {
          isRecordingRef.current = false;
          recorderRef.current = null;
          const blob = new Blob(chunksRef.current, { type: 'video/webm' });
          const reader = new FileReader();
          reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
          reader.readAsDataURL(blob);
        };
        recorder.stop();
      });
    }
  }));

  const renderLoop = async (hideOverlay = false) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    const container = containerRef.current;
    const segmenter = segmentationService.getSegmenter();
    if (!ctx || !container || !segmenter) {
      requestAnimationFrame(() => renderLoop(hideOverlay));
      return;
    }

    const currentScene = sceneRef.current;
    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;

    let mediaW = 16, mediaH = 9;
    if (currentScene.backgroundMedia?.type === 'video' && bgVideoRef.current) {
      mediaW = bgVideoRef.current.videoWidth || 16;
      mediaH = bgVideoRef.current.videoHeight || 9;
    } else if (currentScene.backgroundMedia?.type === 'image' && bgImageRef.current) {
      mediaW = bgImageRef.current.naturalWidth || 16;
      mediaH = bgImageRef.current.naturalHeight || 9;
    }

    const mediaRatio = mediaW / mediaH;
    const containerRatio = containerWidth / containerHeight;
    let finalW, finalH;
    if (containerRatio > mediaRatio) {
      finalH = containerHeight;
      finalW = containerHeight * mediaRatio;
    } else {
      finalW = containerWidth;
      finalH = containerWidth / mediaRatio;
    }

    if (canvas.width !== Math.floor(finalW) || canvas.height !== Math.floor(finalH)) {
      canvas.width = Math.floor(finalW);
      canvas.height = Math.floor(finalH);
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (currentScene.backgroundMedia?.type === 'video' && bgVideoRef.current) {
      ctx.drawImage(bgVideoRef.current, 0, 0, canvas.width, canvas.height);
    } else if (currentScene.backgroundMedia?.type === 'image' && bgImageRef.current) {
      ctx.drawImage(bgImageRef.current, 0, 0, canvas.width, canvas.height);
    } else {
      ctx.fillStyle = '#111';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    if (isStreaming && latestFrame.current) {
      const bitmap = latestFrame.current;
      if (bitmap.width > 0 && bitmap.height > 0) {
        const grabCanvas = grabCanvasRef.current;
        if (grabCanvas.width !== bitmap.width || grabCanvas.height !== bitmap.height) {
          grabCanvas.width = bitmap.width;
          grabCanvas.height = bitmap.height;
        }
        const gCtx = grabCanvas.getContext('2d')!;
        gCtx.drawImage(bitmap, 0, 0);

        const results = segmenter.segmentForVideo(grabCanvas, performance.now());

        if (results && results.confidenceMasks) {
          const personMask = results.confidenceMasks[0];
          const { width, height } = grabCanvas;

          const maskCanvas = maskCanvasRef.current;
          const tempMaskCanvas = tempMaskCanvasRef.current;
          const userCanvas = userCanvasRef.current;

          if (maskCanvas.width !== width) {
            maskCanvas.width = tempMaskCanvas.width = userCanvas.width = width;
            maskCanvas.height = tempMaskCanvas.height = userCanvas.height = height;
          }

          const mCtx = maskCanvas.getContext('2d', { willReadFrequently: true })!;
          const tCtx = tempMaskCanvas.getContext('2d', { willReadFrequently: true })!;
          const uCtx = userCanvas.getContext('2d')!;

          const maskData = personMask.getAsFloat32Array();
          const factor = currentScene.maskSmoothing;
          if (!previousMaskDataRef.current || previousMaskDataRef.current.length !== maskData.length) {
            previousMaskDataRef.current = new Float32Array(maskData);
          } else {
            const prev = previousMaskDataRef.current;
            for (let i = 0; i < maskData.length; i++) {
              prev[i] = prev[i] * factor + maskData[i] * (1 - factor);
            }
          }

          const imageData = tCtx.createImageData(width, height);
          const pixels = imageData.data;
          const smoothMask = previousMaskDataRef.current;
          for (let i = 0; i < smoothMask.length; i++) {
            pixels[i * 4 + 3] = smoothMask[i] * 255;
          }
          tCtx.putImageData(imageData, 0, 0);

          mCtx.clearRect(0, 0, width, height);
          if (currentScene.maskChoke !== 0) {
            const blurAmount = Math.abs(currentScene.maskChoke) / 5;
            mCtx.filter = `blur(${blurAmount}px)`;
            mCtx.drawImage(tempMaskCanvas, 0, 0);
            mCtx.filter = 'none';

            const blurred = mCtx.getImageData(0, 0, width, height);
            const bd = blurred.data;
            const threshold = 128 + (currentScene.maskChoke / 50) * 100;
            for (let i = 3; i < bd.length; i += 4) {
              bd[i] = bd[i] > threshold ? 255 : 0;
            }
            tCtx.putImageData(blurred, 0, 0);
          }

          mCtx.clearRect(0, 0, width, height);
          if (currentScene.maskFeather > 0) {
            mCtx.filter = `blur(${currentScene.maskFeather}px)`;
          }
          mCtx.drawImage(tempMaskCanvas, 0, 0);
          mCtx.filter = 'none';

          uCtx.save();
          uCtx.filter = `brightness(${currentScene.userBrightness}%) contrast(${currentScene.userContrast}%)`;
          uCtx.drawImage(grabCanvas, 0, 0, width, height);
          uCtx.restore();

          uCtx.globalCompositeOperation = 'destination-in';
          uCtx.drawImage(maskCanvas, 0, 0, width, height);
          uCtx.globalCompositeOperation = 'source-over';

          const destHeight = canvas.height * currentScene.userScale;
          const destWidth = (width / height) * destHeight;
          const destX = (currentScene.userX / 100) * canvas.width - destWidth / 2;
          const destY = (currentScene.userY / 100) * canvas.height - destHeight / 2;
          userGeometryRef.current = { x: destX, y: destY, w: destWidth, h: destHeight };

          ctx.save();
          if (currentScene.isFlipped) {
            ctx.translate(destX + destWidth, destY);
            ctx.scale(-1, 1);
            ctx.drawImage(userCanvas, 0, 0, destWidth, destHeight);
          } else {
            ctx.drawImage(userCanvas, destX, destY, destWidth, destHeight);
          }
          ctx.restore();

          if (!hideOverlay && !isRecordingRef.current) {
            ctx.strokeStyle = '#fff';
            ctx.setLineDash([5, 5]);
            ctx.strokeRect(destX, destY, destWidth, destHeight);
            ctx.setLineDash([]);
            ctx.fillStyle = '#fff';
            const corners = [
              { x: destX, y: destY }, { x: destX + destWidth, y: destY },
              { x: destX, y: destY + destHeight }, { x: destX + destWidth, y: destY + destHeight }
            ];
            corners.forEach(c => ctx.fillRect(c.x - 6, c.y - 6, 12, 12));
          }

          results.confidenceMasks.forEach(m => m.close());
        }
      }
    }

    if (!hideOverlay) {
      requestAnimationFrame(() => renderLoop());
    }
  };

  useEffect(() => {
    let active = true;
    const startLoop = () => { if (active) renderLoop(); };
    startLoop();
    return () => { active = false; };
  }, [isStreaming]);

  const handlePointerDown = (e: React.PointerEvent) => {
    const canvas = canvasRef.current;
    if (!canvas || isRecordingRef.current) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const { x: ux, y: uy, w: uw, h: uh } = userGeometryRef.current;

    const h = HANDLE_SIZE + HIT_PADDING;
    let handle: 'tl' | 'tr' | 'bl' | 'br' | '' = '';
    if (Math.abs(x - ux) < h && Math.abs(y - uy) < h) handle = 'tl';
    else if (Math.abs(x - (ux + uw)) < h && Math.abs(y - uy) < h) handle = 'tr';
    else if (Math.abs(x - ux) < h && Math.abs(y - (uy + uh)) < h) handle = 'bl';
    else if (Math.abs(x - (ux + uw)) < h && Math.abs(y - (uy + uh)) < h) handle = 'br';

    if (handle) {
      // Find pinned corner (opposite)
      let fx = ux, fy = uy;
      if (handle === 'tl') { fx = ux + uw; fy = uy + uh; }
      else if (handle === 'tr') { fx = ux; fy = uy + uh; }
      else if (handle === 'bl') { fx = ux + uw; fy = uy; }
      else if (handle === 'br') { fx = ux; fy = uy; }

      interactionRef.current = {
        type: 'resize', startX: e.clientX, startY: e.clientY,
        startUserX: sceneRef.current.userX, startUserY: sceneRef.current.userY,
        startUserScale: sceneRef.current.userScale, resizeHandle: handle,
        fixedX: fx, fixedY: fy,
        startDist: Math.hypot(x - fx, y - fy)
      };
      canvas.style.cursor = (handle === 'tl' || handle === 'br') ? 'nwse-resize' : 'nesw-resize';
    } else if (x >= ux && x <= ux + uw && y >= uy && y <= uy + uh) {
      interactionRef.current = {
        type: 'drag', startX: e.clientX, startY: e.clientY,
        startUserX: sceneRef.current.userX, startUserY: sceneRef.current.userY,
        startUserScale: sceneRef.current.userScale, resizeHandle: '',
        fixedX: 0, fixedY: 0, startDist: 0
      };
      canvas.style.cursor = 'grabbing';
    } else return;

    canvas.setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    const interaction = interactionRef.current;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const curX = e.clientX - rect.left;
    const curY = e.clientY - rect.top;

    // Handle cursor logic when not interacting
    if (interaction.type === 'none') {
      const { x: ux, y: uy, w: uw, h: uh } = userGeometryRef.current;
      const h = HANDLE_SIZE + HIT_PADDING;

      let handle: 'tl' | 'tr' | 'bl' | 'br' | '' = '';
      if (Math.abs(curX - ux) < h && Math.abs(curY - uy) < h) handle = 'tl';
      else if (Math.abs(curX - (ux + uw)) < h && Math.abs(curY - uy) < h) handle = 'tr';
      else if (Math.abs(curX - ux) < h && Math.abs(curY - (uy + uh)) < h) handle = 'bl';
      else if (Math.abs(curX - (ux + uw)) < h && Math.abs(curY - (uy + uh)) < h) handle = 'br';

      if (handle) {
        canvas.style.cursor = (handle === 'tl' || handle === 'br') ? 'nwse-resize' : 'nesw-resize';
      } else if (curX >= ux && curX <= ux + uw && curY >= uy && curY <= uy + uh) {
        canvas.style.cursor = 'grab';
      } else {
        canvas.style.cursor = 'default';
      }
      return;
    }

    // Handle logic during interaction
    if (interaction.type === 'drag') {
      const deltaX = e.clientX - interaction.startX;
      const deltaY = e.clientY - interaction.startY;
      onSceneChange({
        userX: interaction.startUserX + (deltaX / canvas.width) * 100,
        userY: interaction.startUserY + (deltaY / canvas.height) * 100
      });
    } else {
      const curDist = Math.hypot(curX - interaction.fixedX, curY - interaction.fixedY);
      const multiplier = curDist / interaction.startDist;
      const newScale = Math.max(0.1, interaction.startUserScale * multiplier);

      // Keep fixed point (opposite corner) pinned in canvas percentage space
      const fixedPctX = (interaction.fixedX / canvas.width) * 100;
      const fixedPctY = (interaction.fixedY / canvas.height) * 100;

      onSceneChange({ 
        userScale: newScale,
        userX: fixedPctX + (interaction.startUserX - fixedPctX) * multiplier,
        userY: fixedPctY + (interaction.startUserY - fixedPctY) * multiplier
      });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    const interaction = interactionRef.current;
    if (interaction.type === 'none') return;

    interaction.type = 'none';
    if (canvasRef.current) {
      canvasRef.current.releasePointerCapture(e.pointerId);
      // Logic to reset cursor will be handled in next Move event
    }
  };

  return (
    <div ref={containerRef} className="flex-1 relative bg-[#0e0e0e] overflow-hidden flex items-center justify-center p-4">
      <div className="relative shadow-2xl ring-1 ring-white/10 rounded-lg overflow-hidden bg-black flex items-center justify-center">
        <canvas 
          ref={canvasRef} 
          onPointerDown={handlePointerDown} 
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          className="max-w-full max-h-full object-contain" 
        />
      </div>
      <video ref={bgVideoRef} className="hidden" loop autoPlay muted playsInline />
      <img ref={bgImageRef} className="hidden" />
    </div>
  );
});

