interface SidebarProps {
  scene: SceneState;
  onSceneChange: (updates: Partial<SceneState>) => void;
  onSave: () => void;
  onRecord: () => void;
  onStopRecord: () => void;
  isStreaming: boolean;
  isRecording: boolean;
  isCountingDown: boolean;
