              {scene.backgroundMedia ? 'Change background' : 'Select background'}
            </PillButton>
            {scene.backgroundMedia?.type === 'video' && (
              <PillButton onClick={() => onSceneChange({ isBackgroundAudioEnabled: !scene.isBackgroundAudioEnabled })}
                variant={scene.isBackgroundAudioEnabled ? 'solid' : 'outline'}
                icon={<span className="material-symbols-outlined text-[16px]">{scene.isBackgroundAudioEnabled ? 'volume_up' : 'volume_off'}</span>}>
                {scene.isBackgroundAudioEnabled ? 'Mute' : 'Unmute'}
              </PillButton>
            )}
          </div>
        </div>

        {/* Unified Adjustments Section */}
        <div className="flex flex-col gap-2 items-start w-full pb-4">
          <SectionLabel>Adjustments</SectionLabel>
          <div className="flex flex-col gap-1.5 w-full">
            <RangeSlider label="Scale" value={scene.userScale} min={0.1} max={3} step={0.01}
              formatValue={(v) => `${v.toFixed(2)}x`} onChange={(v) => onSceneChange({ userScale: v })} />

            <RangeSlider label="Choke" value={scene.maskChoke} min={-50} max={50} step={1}
              onChange={(v) => onSceneChange({ maskChoke: v })} />

            <RangeSlider label="Feather" value={scene.maskFeather} min={0} max={20} step={1}
              formatValue={(v) => `${v}px`} onChange={(v) => onSceneChange({ maskFeather: v })} />

            <RangeSlider label="Smoothing" value={scene.maskSmoothing} min={0} max={0.95} step={0.01}
              formatValue={(v) => `${Math.round(v * 100)}%`} onChange={(v) => onSceneChange({ maskSmoothing: v })} />

            <RangeSlider label="Brightness" value={scene.userBrightness} min={50} max={200}
              formatValue={(v) => `${v}%`} onChange={(v) => onSceneChange({ userBrightness: v })} />

            <RangeSlider label="Contrast" value={scene.userContrast} min={50} max={200}
              formatValue={(v) => `${v}%`} onChange={(v) => onSceneChange({ userContrast: v })} />
          </div>
        </div>
      </div>

      {/* Primary Actions */}
      <div className="flex flex-col gap-[5px] items-start w-full pt-4 mt-auto">
        {isRecording ? (
          <PillButton variant="filled" onClick={onStopRecord} className="!bg-red-600 hover:!bg-red-500 !text-white"
            icon={<span className="material-symbols-outlined text-[16px]">stop</span>}>Stop</PillButton>
        ) : (
          <PillButton variant="outline" onClick={onRecord} disabled={loading || isCountingDown || !isStreaming}
            icon={<span className="material-symbols-outlined text-[16px]">videocam</span>}>
            {isCountingDown ? 'Ready...' : 'Record'}
          </PillButton>
        )}
        <PillButton variant="solid" onClick={onSave} disabled={loading || isRecording || isCountingDown || !isStreaming}
          icon={<span className="material-symbols-outlined text-[16px]">photo_camera</span>}>
          Capture screenshot
        </PillButton>
      </div>
    </div>
  );
};

