import React, { useState, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { SceneState } from './types';
import Sidebar from './components/Sidebar';
import CanvasStage, { CanvasStageHandle } from './components/CanvasStage';
import PreviewModal from './components/PreviewModal';
import { useWebcam } from './hooks/useWebcam';

const INITIAL_STATE: SceneState = {
  userX: 50,
  userY: 60,
  userScale: 0.8,
  userBrightness: 100,
  userContrast: 100,
  maskThreshold: 0.5,
  maskBlur: 0,
  maskChoke: 5,
  maskFeather: 4,
  maskSmoothing: 0.45,
  showOverlay: true,
  backgroundMedia: null,
  isBackgroundAudioEnabled: false,
  isFlipped: true,
};

interface PreviewMedia {
  base64: string;
  mimeType: string;
}

export default function App() {
  const [scene, setScene] = useState<SceneState>(INITIAL_STATE);
  const [loading, setLoading] = useState(false);
  const [previewMedia, setPreviewMedia] = useState<PreviewMedia | null>(null);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const [isRecording, setIsRecording] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [recordTime, setRecordTime] = useState(0);

  const { start, stop, isStreaming, latestFrame } = useWebcam();
  const stageRef = useRef<CanvasStageHandle>(null);
  const recordStartTimeRef = useRef<number>(0);

  useEffect(() => {
    start();
  }, []);

  useEffect(() => {
    const id = 'webcam-stage-css';
    if (!document.getElementById(id)) {
      const style = document.createElement('style');
      style.id = id;
      style.textContent = `
        .material-symbols-outlined { font-size: 16px !important; width: 16px !important; height: 16px !important; line-height: 1 !important; display: inline-block !important; vertical-align: middle; }
        input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
        input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
        input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
        input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', sans-serif; overflow: hidden; }
        @keyframes pulse-record { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
        .animate-record { animation: pulse-record 1s infinite; }
        @keyframes countdown-pop { 0% { transform: scale(0.5); opacity: 0; } 50% { transform: scale(1.2); opacity: 1; } 100% { transform: scale(1); opacity: 1; } }
        .animate-countdown { animation: countdown-pop 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `;
      document.head.appendChild(style);
      const fontLink = document.createElement('link');
      fontLink.rel = 'stylesheet';
      fontLink.href = 'https://fonts.googleapis.com/css2?family=Google+Sans+Text:wght@400;500;700&family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0';
      document.head.appendChild(fontLink);
    }
  }, []);

  useEffect(() => {
    let interval: any;
    if (isRecording) {
      recordStartTimeRef.current = Date.now();
      interval = setInterval(() => { setRecordTime((Date.now() - recordStartTimeRef.current) / 1000); }, 100);
    } else { setRecordTime(0); }
    return () => clearInterval(interval);
  }, [isRecording]);

  const handleSceneChange = (updates: Partial<SceneState>) => { setScene(prev => ({ ...prev, ...updates })); };
  const handleToggleStream = () => { if (isStreaming) stop(); else start(); };

  const handleCaptureClick = async () => {
    if (!stageRef.current) return;
    setLoading(true);
    try {
      const base64 = await stageRef.current.capture();
      setPreviewMedia({ base64, mimeType: 'image/png' });
      setIsPreviewOpen(true);
      Flow.save({ base64, mimeType: 'image/png', name: 'Webcam Capture' }).catch(() => {});
    } catch (err) { console.error('Capture failed:', err); } finally { setLoading(false); }
  };

  const handleRecordClick = async () => {
    if (!stageRef.current || isRecording || countdown !== null) return;
    let count = 3;
    setCountdown(count);
    const interval = setInterval(() => {
      count--;
      if (count > 0) setCountdown(count);
      else { clearInterval(interval); setCountdown(null); setIsRecording(true); stageRef.current?.startRecording(); }
    }, 1000);
  };

  const handleStopRecording = async () => {
    if (!stageRef.current || !isRecording) return;
    setLoading(true);
    try {
      const result = await stageRef.current.stopRecording();
      setPreviewMedia({ base64: result, mimeType: 'video/mp4' });
      setIsPreviewOpen(true);
      Flow.save({ base64: result, mimeType: 'video/mp4', name: 'Webcam Recording' }).catch(() => {});
    } catch (err) { console.error('Recording failed:', err); } finally { setIsRecording(false); setLoading(false); }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e]">
      <div className="flex-1 flex flex-col min-w-0 relative">
        <CanvasStage ref={stageRef} scene={scene} onSceneChange={handleSceneChange} 
          latestFrame={latestFrame} isStreaming={isStreaming} forceMute={isPreviewOpen} />
        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/20 pointer-events-none z-40">
            <div className="text-white text-9xl font-bold animate-countdown">{countdown}</div>
          </div>
        )}
        {isRecording && (
          <div className="absolute top-8 left-1/2 -translate-x-1/2 flex flex-col items-center gap-3 z-40">
            <div className="flex items-center gap-2 bg-red-600/90 backdrop-blur px-4 py-1.5 rounded-full shadow-lg">
              <div className="w-2.5 h-2.5 rounded-full bg-white animate-record" />
              <span className="text-white text-sm font-bold tracking-widest uppercase">{recordTime.toFixed(1)}s Recording</span>
            </div>
          </div>
        )}
      </div>
      <Sidebar scene={scene} onSceneChange={handleSceneChange} onSave={handleCaptureClick} onRecord={handleRecordClick}
        onStopRecord={handleStopRecording} isStreaming={isStreaming} isRecording={isRecording}
        isCountingDown={countdown !== null} onToggleStream={handleToggleStream} loading={loading} />
      <PreviewModal isOpen={isPreviewOpen} media={previewMedia} onClose={() => setIsPreviewOpen(false)} />
    </div>
  );
}

import React from 'react';
import { PillButton } from './UIComponents';

interface PreviewMedia {
  base64: string;
  mimeType: string;
}

interface PreviewModalProps {
  isOpen: boolean;
  media: PreviewMedia | null;
  onClose: () => void;
}

const PreviewModal: React.FC<PreviewModalProps> = ({
  isOpen,
  media,
  onClose,
}) => {
  if (!isOpen || !media) return null;

  const isVideo = media.mimeType.startsWith('video/');

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/90 backdrop-blur-md" onClick={onClose} />

      {/* Modal Content */}
      <div className="relative w-full max-w-4xl bg-[#1a1a1a] border border-[#595959] rounded-2xl overflow-hidden shadow-2xl flex flex-col md:flex-row animate-dropdown">

        {/* Media Side */}
        <div className="flex-1 bg-black flex items-center justify-center relative min-h-[300px] md:min-h-[500px]">
          {isVideo ? (
            <video 
              src={`data:${media.mimeType};base64,${media.base64}`} 
              className="max-w-full max-h-full object-contain"
              controls
              autoPlay
              loop
            />
          ) : (
            <img 
              src={`data:${media.mimeType};base64,${media.base64}`} 
              className="max-w-full max-h-full object-contain"
              alt="Captured Scene"
            />
          )}
        </div>

        {/* Sidebar Side */}
        <div className="w-full md:w-[300px] p-6 flex flex-col gap-6 bg-[#1a1a1a] justify-center text-center md:text-left">
          <div className="flex flex-col gap-2">
            <h2 className="text-white text-xl font-bold tracking-tight">
              {isVideo ? 'Video Recorded' : 'Scene Captured'}
            </h2>
            <p className="text-[rgba(218,220,224,0.7)] text-[13px] leading-relaxed">
              Successfully saved to your gallery.
            </p>
          </div>

          <div className="mt-auto md:mt-0">
            <PillButton 
              variant="solid" 
              onClick={onClose}
              icon={<span className="material-symbols-outlined text-[16px]">check</span>}
            >
              Close
            </PillButton>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PreviewModal;
